// @extension-target: customer-account.order-status.block.render
import '@shopify/ui-extensions/preact';
import {render} from 'preact';

export default async () =&gt; {
  render(&lt;Extension /&gt;, document.body);
};

function Extension() {
  const {shouldShowBanner} =
    shopify.customerPrivacy.value;

  if (!shouldShowBanner) {
    return null;
  }

  async function acceptAll() {
    await shopify.applyTrackingConsentChange({
      type: 'changeVisitorConsent',
      analytics: true,
      marketing: true,
      preferences: true,
      saleOfData: false,
    });
  }

  async function declineAll() {
    await shopify.applyTrackingConsentChange({
      type: 'changeVisitorConsent',
      analytics: false,
      marketing: false,
      preferences: false,
      saleOfData: true,
    });
  }

  return (
    &lt;s-banner tone="info"&gt;
      &lt;s-stack direction="block" gap="small-200"&gt;
        &lt;s-text&gt;
          We use cookies to improve your
          experience. Choose your preferences.
        &lt;/s-text&gt;
        &lt;s-stack direction="inline" gap="base"&gt;
          &lt;s-button onClick={acceptAll}&gt;
            Accept all
          &lt;/s-button&gt;
          &lt;s-button
            variant="secondary"
            onClick={declineAll}
          &gt;
            Decline all
          &lt;/s-button&gt;
        &lt;/s-stack&gt;
      &lt;/s-stack&gt;
    &lt;/s-banner&gt;
  );
}

// @extension-target: customer-account.order-status.block.render
import '@shopify/ui-extensions/preact';
import {render} from 'preact';

export default async () =&gt; {
  render(&lt;Extension /&gt;, document.body);
};

function consentLabel(value) {
  if (value === true) return 'Granted';
  if (value === false) return 'Denied';
  return 'No decision';
}

function saleOfDataLabel(value) {
  if (value === true) return 'Opted out';
  if (value === false) return 'Not opted out';
  return 'No decision';
}

function Extension() {
  const {visitorConsent} =
    shopify.customerPrivacy.value;

  const categories = [
    {label: 'Analytics', display: consentLabel(visitorConsent?.analytics)},
    {label: 'Marketing', display: consentLabel(visitorConsent?.marketing)},
    {label: 'Preferences', display: consentLabel(visitorConsent?.preferences)},
    {label: 'Sale of data', display: saleOfDataLabel(visitorConsent?.saleOfData)},
  ];

  return (
    &lt;s-box padding="base"&gt;
      &lt;s-stack direction="block" gap="small-200"&gt;
        &lt;s-text type="strong"&gt;
          Privacy Consent Status
        &lt;/s-text&gt;
        {categories.map((category) =&gt; (
          &lt;s-stack
            key={category.label}
            direction="inline"
            gap="base"
          &gt;
            &lt;s-text type="strong"&gt;
              {category.label}:
            &lt;/s-text&gt;
            &lt;s-text&gt;
              {category.display}
            &lt;/s-text&gt;
          &lt;/s-stack&gt;
        ))}
      &lt;/s-stack&gt;
    &lt;/s-box&gt;
  );
}

// @extension-target: customer-account.order-status.block.render
import '@shopify/ui-extensions/preact';
import {render} from 'preact';
import {useState} from 'preact/hooks';

export default async () =&gt; {
  render(&lt;Extension /&gt;, document.body);
};

function Extension() {
  const [status, setStatus] = useState('');

  async function grantAnalyticsOnly() {
    try {
      const result =
        await shopify.applyTrackingConsentChange({
          type: 'changeVisitorConsent',
          analytics: true,
          marketing: false,
          preferences: false,
          saleOfData: true,
        });

      if (result.type === 'success') {
        setStatus('Preferences saved.');
      } else {
        setStatus('Failed to save preferences.');
      }
    } catch (error) {
      setStatus('An error occurred.');
    }
  }

  return (
    &lt;s-box padding="base"&gt;
      &lt;s-stack direction="block" gap="small-200"&gt;
        &lt;s-text type="strong"&gt;
          Cookie Preferences
        &lt;/s-text&gt;
        &lt;s-text&gt;
          Allow only essential cookies and
          analytics to help us improve your
          experience.
        &lt;/s-text&gt;
        &lt;s-button onClick={grantAnalyticsOnly}&gt;
          Save preferences
        &lt;/s-button&gt;
        {status && (
          &lt;s-text color="subdued"&gt;
            {status}
          &lt;/s-text&gt;
        )}
      &lt;/s-stack&gt;
    &lt;/s-box&gt;
  );
}

