  const translate = shopify.i18n.translate;

  return (
    &lt;s-customer-account-action
      heading={translate('menuAction.title')}
    &gt;
      &lt;s-button
        slot="primary-action"
        onClick={() =&gt; shopify.close()}
      &gt;
        {translate('menuAction.primaryAction')}
      &lt;/s-button&gt;
      &lt;s-paragraph&gt;
        {translate('menuAction.content')}
      &lt;/s-paragraph&gt;
    &lt;/s-customer-account-action&gt;
  );
}

